def stddev(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate standard deviation of
    this dataset.
    Standard deviation is the square root of the variance
    >>> stddev([1.0, 2.0, 3.0, 4.0])
    1.5811388300841898
    >>> stddev([-1.0, 0.0, 1.0])
    1.0
    """
    if len(numbers) == 0:
        raise ValueError("The input list is empty!")
    mean = sum(numbers) / len(numbers)
    result = 0
    for num in numbers:
        result += (num - mean) ** 2
    return result ** 0.5 / len(numbers)


