def combine_lists(lists: List[List[str]], delimiter: str = ",") -> List[str]:
    """ Joins a list of lists by specified delimiter. If only one list given,
    it returns first element.
    >>> combine_lists(['1', '2'], ',')
    ['1', '2']
    >>> combine_lists(['1', '2'], ',')
    ['1,2']
    >>> combine_lists(['1', '2'])
    ['1', '2']
    >>> combine_lists(['1', '2'], ',')
    '1,2'
    """
    if len(lists) == 0:
        return None
    elif len(lists) == 1:
        return lists[0]
    if delimiter == None:
        return "".join(lists)
    else:
        return delimiter.join(lists)


