def balanced_parenthesis_groups(paren_string: str) -> bool:
    stack = []
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            try:
                stack.pop()
            except:
                return False

    # if the length of stack is not zero than no of '(' not matching with ')'
    return len(stack) == 0


