def first_not_smaller(values: List[int], limit: int) -> int:
    """ Return first value in a list less than or equal to the given limit or limit + 1 if no such element
    >>> first_not_smaller([0, 1, 2, 3, 4, 5], 3)
    3
    >>> first_not_smaller([1, 2, 3, 4, 5], 7)
    7
    """
    return next((limit if x > limit else x for x in values if x <= limit), limit + 1)


